// Blink — the first sketch everyone writes.
//
// An LED and a 220 ohm resistor on pin 13, which is also the Uno's built-in LED,
// so both blink together. Press Run to compile it and watch.

void setup() {
  pinMode(13, OUTPUT);
}

void loop() {
  digitalWrite(13, HIGH);
  delay(500);
  digitalWrite(13, LOW);
  delay(500);
}
